package com.productivitysuite.service;
import com.productivitysuite.dto.planning.*; import com.productivitysuite.entity.*; import com.productivitysuite.exception.ResourceNotFoundException; import com.productivitysuite.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor @Transactional public class DailyPlanService {
 private final DailyPlanRepository plans; private final EnergyLogRepository energy; private final DailyCommitmentRepository commitments; private final UserRepository users; private final TaskRepository tasks; private final PlanningService events;
 @Transactional(readOnly=true) public List<PlanResponse> list(UUID uid, LocalDate date){return plans.findByUserIdAndPlanDateOrderByVersionDesc(uid,date).stream().map(this::out).toList();}
 public PlanResponse create(UUID uid, PlanRequest r){User u=users.findById(uid).orElseThrow(); validate(u,r); int v=plans.findByUserIdAndPlanDateOrderByVersionDesc(uid,r.getPlanDate()).stream().findFirst().map(p->p.getVersion()+1).orElse(1); DailyPlan p=DailyPlan.builder().user(u).planDate(r.getPlanDate()).version(v).windowStart(r.getWindowStart()).windowEnd(r.getWindowEnd()).source(r.getSource()==null?"ai":r.getSource()).assumptions(r.getAssumptions()==null?List.of():r.getAssumptions()).summary(r.getSummary()).build(); for(PlanItemRequest i:r.getItems()){PlanItem x=PlanItem.builder().plan(p).title(i.getTitle()).startTime(i.getStartTime()).endTime(i.getEndTime()).bufferMinutes(i.getBufferMinutes()).energyLevel(i.getEnergyLevel()).itemType(i.getItemType()).notes(i.getNotes()).itemOrder(i.getItemOrder()).task(i.getTaskId()==null?null:tasks.findByIdAndUserId(i.getTaskId(),uid).orElseThrow(()->new ResourceNotFoundException("Task",i.getTaskId()))).build();p.getItems().add(x);} DailyPlan saved=plans.save(p); events.record(uid,"plan.proposed","daily_plan",saved.getId(),Map.of("date",r.getPlanDate().toString(),"version",v)); return out(saved);}
 public PlanResponse approve(UUID uid, UUID id){DailyPlan p=owned(uid,id); if(p.getStatus()!=DailyPlan.PlanStatus.DRAFT)throw new IllegalArgumentException("Only draft plans can be approved"); User u=users.findById(uid).orElseThrow(); PlanRequest review=new PlanRequest(); review.setPlanDate(p.getPlanDate());review.setWindowStart(p.getWindowStart());review.setWindowEnd(p.getWindowEnd());review.setItems(p.getItems().stream().map(item->{PlanItemRequest i=new PlanItemRequest();i.setTaskId(item.getTask()==null?null:item.getTask().getId());i.setTitle(item.getTitle());i.setStartTime(item.getStartTime());i.setEndTime(item.getEndTime());i.setItemType(item.getItemType());return i;}).toList());validate(u,review);for(DailyPlan previous:plans.findByUserIdAndPlanDateOrderByVersionDesc(uid,p.getPlanDate())){if(previous.getStatus()==DailyPlan.PlanStatus.APPROVED)previous.setStatus(DailyPlan.PlanStatus.SUPERSEDED);} p.setStatus(DailyPlan.PlanStatus.APPROVED); events.record(uid,"plan.approved","daily_plan",id,Map.of("date",p.getPlanDate().toString())); return out(p);}
 public PlanResponse replan(UUID uid, UUID id, PlanRequest r){DailyPlan old=owned(uid,id);if(!old.getPlanDate().equals(r.getPlanDate()))throw new IllegalArgumentException("Replan date must match");PlanResponse next=create(uid,r);events.record(uid,"plan.replanned","daily_plan",next.getId(),Map.of("previousPlanId",id.toString()));return next;}
 public EnergyLog logEnergy(UUID uid, EnergyRequest r){User u=users.findById(uid).orElseThrow();EnergyLog saved=energy.save(EnergyLog.builder().user(u).energy((short)r.getEnergy()).mood(r.getMood()==null?null:r.getMood().shortValue()).source(r.getSource()).notes(r.getNotes()).build());events.record(uid,"energy.logged","energy_log",saved.getId(),Map.of("energy",saved.getEnergy()));return saved;}
 private void validate(User u,PlanRequest r){
  if(!r.getWindowEnd().isAfter(r.getWindowStart()))throw new IllegalArgumentException("Plan window must be valid");
  if(r.getItems()==null||r.getItems().isEmpty())throw new IllegalArgumentException("Plan requires items");
  if(r.getPlanDate().isBefore(LocalDate.now(ZoneId.of(u.getTimezone()))))throw new IllegalArgumentException("Cannot plan in the past");
  if(r.getPlanDate().equals(LocalDate.now(ZoneId.of(u.getTimezone()))) && LocalDateTime.of(r.getPlanDate(),r.getWindowStart()).isBefore(LocalDateTime.now(ZoneId.of(u.getTimezone())).withSecond(0).withNano(0).plusMinutes(15)))
   throw new IllegalArgumentException("Today's plan must begin at least 15 minutes from now");
  List<PlanItemRequest> ordered=r.getItems().stream().sorted(Comparator.comparing(PlanItemRequest::getStartTime)).toList();
  for(int j=0;j<ordered.size();j++){PlanItemRequest i=ordered.get(j);if(!i.getEndTime().isAfter(i.getStartTime())||i.getStartTime().isBefore(r.getWindowStart())||i.getEndTime().isAfter(r.getWindowEnd()))throw new IllegalArgumentException("Plan item has invalid timing");if("task".equals(i.getItemType())&&i.getTaskId()==null)throw new IllegalArgumentException("Task item must reference a saved task");if(j>0&&i.getStartTime().isBefore(ordered.get(j-1).getEndTime()))throw new IllegalArgumentException("Plan items overlap");}
  for(DailyCommitment c:commitments.findByUserIdOrderByStartTime(u.getId())){boolean applies=!c.isRecurring()&&r.getPlanDate().equals(c.getDate());if(c.isRecurring()&&c.getDaysOfWeek()!=null)for(short day:c.getDaysOfWeek())if(day==r.getPlanDate().getDayOfWeek().getValue())applies=true;if(!applies||c.isFlexible())continue;
   LocalTime clippedStart=c.getStartTime().isBefore(r.getWindowStart())?r.getWindowStart():c.getStartTime(); LocalTime clippedEnd=c.getEndTime().isAfter(r.getWindowEnd())?r.getWindowEnd():c.getEndTime();
   if(!clippedEnd.isAfter(clippedStart))continue;
   if(ordered.stream().noneMatch(i->"commitment".equals(i.getItemType())&&c.getTitle().equals(i.getTitle())&&!i.getStartTime().isAfter(clippedStart)&&!i.getEndTime().isBefore(clippedEnd)))throw new IllegalArgumentException("Plan must include fixed commitment: "+c.getTitle());
   for(PlanItemRequest i:ordered){if(!"commitment".equals(i.getItemType())&&i.getStartTime().isBefore(c.getEndTime())&&i.getEndTime().isAfter(c.getStartTime()))throw new IllegalArgumentException("Plan conflicts with fixed commitment: "+c.getTitle());}}
 }
 private DailyPlan owned(UUID uid,UUID id){return plans.findByIdAndUserId(id,uid).orElseThrow(()->new ResourceNotFoundException("Daily plan",id));}
 private PlanResponse out(DailyPlan p){return PlanResponse.builder().id(p.getId()).planDate(p.getPlanDate()).version(p.getVersion()).status(p.getStatus()).windowStart(p.getWindowStart()).windowEnd(p.getWindowEnd()).source(p.getSource()).assumptions(p.getAssumptions()).summary(p.getSummary()).items(p.getItems().stream().map(i->PlanResponse.PlanItemResponse.builder().id(i.getId()).taskId(i.getTask()==null?null:i.getTask().getId()).title(i.getTitle()).startTime(i.getStartTime()).endTime(i.getEndTime()).bufferMinutes(i.getBufferMinutes()).energyLevel(i.getEnergyLevel()).itemType(i.getItemType()).status(i.getStatus()).notes(i.getNotes()).itemOrder(i.getItemOrder()).build()).toList()).build();}
}
